import json, os, time, urllib.request, urllib.error
raw = os.environ["BLAND_API_KEY"].strip()
if raw.startswith("{"):
    p = json.loads(raw); raw = next((p[k] for k in ("api_key", "key", "value") if p.get(k)), raw)
PW = "94abad8b-fbe2-4e67-9c64-d9b586dd2653"

def call(path, payload=None):
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request("https://api.bland.ai" + path, data=data, method="POST" if data else "GET", headers={"Authorization": raw, "Content-Type": "application/json", "User-Agent": "mybcat-cli"})
    try:
        with urllib.request.urlopen(req, timeout=90) as r:
            return r.status, json.loads(r.read().decode() or "{}")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode(errors="replace")[:200]

print("=== SECTION 1: START MARKERS v123 vs v124 (stored) ===")
graphs = {}
for v in (123, 124):
    s, b = call("/v1/pathway/%s/version/%s" % (PW, v))
    g = b.get("data") if isinstance(b, dict) and isinstance(b.get("data"), dict) else b
    graphs[v] = g
    nodes = g.get("nodes") or []
    print("v%s HTTP %s nodes=%d first_node=%s" % (v, s, len(nodes), nodes[0].get("id") if nodes else None))
    for n in nodes:
        d = n.get("data") or {}
        flags = {k: d.get(k) for k in ("isStart", "active", "isGlobal") if d.get(k)}
        tflags = {k: n.get(k) for k in ("isStart", "active", "type") if n.get(k)}
        if flags or tflags.get("isStart") or tflags.get("active"):
            print("  v%s node=%s data_flags=%s top_flags=%s" % (v, n.get("id"), flags, tflags))
print("MARKERS_DONE")

print("=== SECTION 2: stored v124 vs sent draft-v124.json ===")
draft = json.load(open("/home/ankit114/repos/ringer/my-manifests/mk2-number-and-comeback/workMint124/build-validate-mint-124/draft-v124.json"))
live = graphs[124]
dn = {str(n.get("id")): n for n in (draft.get("nodes") or [])}
ln = {str(n.get("id")): n for n in (live.get("nodes") or [])}
diffs = 0
for nid in sorted(set(dn) | set(ln)):
    a, b = dn.get(nid), ln.get(nid)
    if a is None or b is None:
        print("NODE %s only in %s" % (nid, "live" if a is None else "draft")); diffs += 1; continue
    if json.dumps(a, sort_keys=True) != json.dumps(b, sort_keys=True):
        keys = set((a.get("data") or {})) | set((b.get("data") or {}))
        ck = [k for k in sorted(keys) if json.dumps((a.get("data") or {}).get(k), sort_keys=True) != json.dumps((b.get("data") or {}).get(k), sort_keys=True)]
        print("NODE %s differs data_fields=%s" % (nid, ck)); diffs += 1
print("STORED_VS_SENT_DIFFS=%d" % diffs)
print("DIFF_DONE")

print("=== SECTION 3: chat repro x3 per version (no start_node, like the battery) ===")
reqd = {"recall_patient_id": "4376662466", "recall_cell": "6468942428", "store": "711", "campaign": "harness"}
for v in (123, 124):
    for i in range(3):
        s, b = call("/v1/pathway/chat/create", {"pathway_id": PW, "pathway_version": v, "request_data": reqd})
        d = b.get("data") if isinstance(b, dict) else {}
        cid = d.get("chat_id") if isinstance(d, dict) else None
        n0 = d.get("current_node_id") if isinstance(d, dict) else None
        if not cid:
            print("REPRO v%s run%d CREATE_FAIL HTTP %s %s" % (v, i + 1, s, str(b)[:120]))
            continue
        s2, b2 = call("/v1/pathway/chat/%s" % cid, {"message": "hi"})
        d2 = b2.get("data") if isinstance(b2, dict) else {}
        n1 = d2.get("current_node_id") if isinstance(d2, dict) else None
        print("REPRO v%s run%d create_node=%s after_hi_node=%s" % (v, i + 1, n0, n1))
        time.sleep(1)
print("REPRO_DONE")
